import { Component } from '@angular/core';
import { AuthClientesService } from '../../../auth/auth.service';
import { FormsModule } from '@angular/forms';

@Component({
    selector: 'app-change-password',
    imports: [
        FormsModule
    ],
    templateUrl: './change-pass.component.html',
    styleUrl: './change-pass.component.css'
})
export class ChangePasswordComponent {
  oldPass:string=''
  newPass=''
  confirmPass=''

  constructor(
    private auth: AuthClientesService,
  ) {}

  public isFormValid():boolean{
    return !!this.newPass && this.newPass===this.confirmPass
  }

  public async updatePass(){
    this.auth.updatePass(this.oldPass, this.newPass)
  }
}
